/// A mark, `class="icon"` and a class of its own, hidden from assistive
/// technology.
pub fn mark(mark: Mark, class: &'static str) -> impl IntoView + use<> {
    let (width, height, path) = mark;
    view! {
        <svg class=format!("icon {class}") viewBox=format!("0 0 {width} {height}") aria-hidden="true" focusable="false">
            <path d=path fill="currentColor"></path>
        </svg>
    }
}
